import{_ as r,C as n,o as i,c as o,j as t,a,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const l="/screenshots/vscode-testing.png",b=JSON.parse(`{"title":"Runs from the editor","description":"Run Playwright tests from VS Code or a JetBrains IDE and follow the run in the status bar: the editor reads its results within a second of its end, lays them over the latest CI run's failures, and says when a run never reached the instance.","frontmatter":{"title":"Runs from the editor","description":"Run Playwright tests from VS Code or a JetBrains IDE and follow the run in the status bar: the editor reads its results within a second of its end, lays them over the latest CI run's failures, and says when a run never reached the instance.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/editor-runs.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/editor-runs.html"}],["meta",{"property":"og:title","content":"Runs from the editor | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Run Playwright tests from VS Code or a JetBrains IDE and follow the run in the status bar: the editor reads its results within a second of its end, lays them over the latest CI run's failures, and says when a run never reached the instance."}]]},"headers":[],"relativePath":"features/editor-runs.md","filePath":"features/editor-runs.md","lastUpdated":1795038533000}`),u={name:"features/editor-runs.md"};function c(g,e,f,w,p,m){const s=n("Needs");return i(),o("div",null,[e[0]||(e[0]=t("h1",{id:"runs-from-the-editor",tabindex:"-1"},[a("Runs from the editor "),t("a",{class:"header-anchor",href:"#runs-from-the-editor","aria-label":'Permalink to "Runs from the editor"'},"​")],-1)),h(s,{editor:""}),e[1]||(e[1]=d('<p>The <a href="./editors.html">editor extensions</a> run your tests where you edit them, then show a run&#39;s progress in the status bar and its results over the latest CI run&#39;s <a href="./editor-failures.html">failures</a>.</p><h2 id="run-tests" tabindex="-1">Run tests <a class="header-anchor" href="#run-tests" aria-label="Permalink to &quot;Run tests&quot;">​</a></h2><ul><li>The lines above a locator line, an application file or a page file (CodeLens in VS Code, Code Vision in a JetBrains IDE) run the tests they name when clicked; those of a server file record its <a href="./editor-coverage.html#refresh-the-marks-with-a-local-run">coverage</a>.</li><li><strong>Piwi: Run the test at the cursor</strong> (<code>Ctrl+Shift+Alt+K</code>, <code>Cmd+Shift+Alt+K</code> on macOS, another <a href="/reference/editor-commands.html#keys">key</a> in some JetBrains keymaps) runs the test whose <code>test(…)</code> call holds the cursor, and <strong>Piwi: Run this spec</strong> every test of the spec; both in the editor&#39;s <strong>Piwi</strong> submenu on a spec and under VS Code&#39;s editor title Run button (the caret in a JetBrains IDE), saving the spec first. <strong>Run</strong> in VS Code&#39;s test hover runs it, as <a href="#the-testing-view-vs-code">the Testing view</a> does. A test the instance does not know, such as one just <a href="./editor-recording.html#run-it-or-verify-it-three-times">recorded</a>, runs by the line of its <code>test(…)</code> call, with or without an instance.</li><li><strong>Piwi: Debug the test at the cursor</strong> (<strong>Debug the test at the caret</strong>) runs it as <strong>Debug with Piwi</strong> does: headed, at <a href="./editor-breakpoints.html">your breakpoints</a>, holding each failure at its line.</li><li><strong>Piwi: Verify the test at the cursor ×3</strong> (<strong>Verify the test at the caret ×3</strong>) runs that test three times as a <a href="#when-your-run-ends">verification</a>.</li><li><strong>Piwi: Run the tests that reach this file</strong> runs every test reaching the active file through <a href="/features/code-reach.html">code reach</a>; also in the editor&#39;s and the file tree&#39;s <strong>Piwi</strong> submenu.</li><li><strong>Piwi: Run a saved selection…</strong> runs a <a href="/features/test-selection.html">selection</a>.</li></ul><p>The command, <code>npx playwright test</code> with the arguments <code>piwi run</code> would pass, runs from the Playwright config&#39;s folder: as a task in VS Code, in a terminal of its own (<strong>Tasks: Rerun Last Task</strong> restarts it), in the Run tool window in a JetBrains IDE, its tests in a test tree beside the output as they run (<strong>Rerun</strong> restarts it), or in the IDE&#39;s Playwright runner (Debug, <strong>Rerun Failed Tests</strong>), a choice of <strong>Settings → Tools → Piwi</strong>, offered once, that keeps every control of a Piwi run, through the runner&#39;s Rerun and Debug too. It sets <code>PIWI_ORIGIN=editor</code> and its own <code>PIWI_ORIGIN_REF</code> (<a href="/reference/test-metadata.html#run-origin">run origin</a>), by which the editor finds its run. Breakpoints and the editor pause it: <a href="./editor-run-control.html">Pause and step from the editor</a>.</p><h2 id="how-a-run-starts" tabindex="-1">How a run starts <a class="header-anchor" href="#how-a-run-starts" aria-label="Permalink to &quot;How a run starts&quot;">​</a></h2><p>Two choices apply to every run: <strong>Run headed</strong> (<code>--headed</code>, a verification included) and <a href="./watch-a-run.html#hold-failures"><strong>Hold failures</strong></a> <strong>Auto</strong>, <strong>On</strong> or <strong>Off</strong> from the run&#39;s start. Auto lets Piwi decide: on with your breakpoints or a <code>page.pause()</code>, headed for the latter. <strong>Piwi: Turn headed runs on or off</strong> and <strong>Piwi: Hold failures from each run&#39;s start…</strong> set them (in VS Code, <code>piwi.runHeaded</code> and <code>piwi.runHoldFailures</code>, shown in the status bar&#39;s tooltip and offered together by <strong>Piwi: Run options…</strong>). A <a href="./debug-in-editor.html">debug run</a>, a Flake Lab line and a fix plan&#39;s check leave them out.</p><h2 id="the-testing-view-vs-code" tabindex="-1">The Testing view (VS Code) <a class="header-anchor" href="#the-testing-view-vs-code" aria-label="Permalink to &quot;The Testing view (VS Code)&quot;">​</a></h2><p>VS Code&#39;s Testing view lists the tests <code>playwright test --list</code> gives for each config, under their folders and <code>test.describe</code> blocks, a test of several Playwright projects with a node per project, each with its latest result and duration, and where and why it failed (<strong>Peek Error</strong>). A spec is listed again when saved, and read from its text while you edit it. A config Playwright cannot list says why. Tests only your instance knows go in <strong>Not in this checkout</strong>, which does not run. Results are published as a test run (<code>Piwi: run #120 on main</code>); a run in progress shows each test as it begins and ends. Its gutter shows each result in place of Piwi&#39;s icon; the line keeps Piwi&#39;s hover. A flaky test shows as passed, its line ending with <em>flaky</em>. An item is named by its test&#39;s title alone, as a screen reader reads it, and the view&#39;s filter finds tests by <code>@piwi:flaky</code>, <code>@piwi:quarantined</code>, a Playwright tag (<code>@piwi:@smoke</code>) or an owner (<code>@piwi:owner:ada</code>). With the view off, Piwi&#39;s gutter marks a test with no recent result with a dashed ring.</p><p>Each test&#39;s actions are one list in both editors: <strong>Run with Piwi</strong>, <strong>Debug with Piwi</strong> and <strong>Verify ×3 with Piwi</strong>, <strong>Record steps in this test…</strong> (a <a href="./editor-recording.html">recording</a> after the last line of its body), a failure&#39;s trace and screenshot, <strong>Open in dashboard</strong>, <strong>Copy context for agent</strong>, then the test&#39;s Flake Lab commands. <strong>More…</strong> on the <a href="./editor-test-card.html">test&#39;s card</a> opens them, and in VS Code <strong>Piwi: Show the test&#39;s actions…</strong> from the Testing view&#39;s gutter and menus, and the line number&#39;s menu with the view off; in a JetBrains IDE, a right-click on the result icon. The IDE&#39;s own run icon offers <strong>Run with Piwi</strong> and <strong>Verify ×3 with Piwi</strong> too; turning off <strong>Piwi test results</strong> under <strong>Gutter Icons</strong> hides the result icon and its list.</p><figure><img src="'+l+'" alt="VS Code: the Testing view lists the spec&#39;s tests with their latest results, and a failing test&#39;s error is peeked at its line in the spec"><figcaption>The Testing view with the latest run&#39;s results, and why <strong>pays by card</strong> failed, at its line.</figcaption></figure><p><strong>Run with Piwi</strong>, the view&#39;s run profile, runs what you pick by the narrowest filter Playwright takes: a config whole, a folder or a spec by its path, a describe block or a test by its line (a loop&#39;s by its title), a project&#39;s node with <code>--project</code>. <strong>Debug with Piwi</strong> runs them headed at your breakpoints, holding each failure, and <strong>Verify ×3 with Piwi</strong> runs them three times. Under Run with Coverage, it also shows their coverage in the Test Coverage view (<a href="./editor-coverage.html">Editor coverage</a>). From a failed test&#39;s actions, <strong>Debug with Piwi</strong> runs it as <a href="./debug-in-editor.html">Debug in my editor</a> does, stopping once at the line it failed through. A test the run gave Piwi no result for passes when the command exited with 0, else is an error. Debug runs Piwi&#39;s run control, not a debug session. <code>piwi.testExplorer</code> turns the view&#39;s Piwi tests off.</p><h2 id="re-run-the-failing-tests" tabindex="-1">Re-run the failing tests <a class="header-anchor" href="#re-run-the-failing-tests" aria-label="Permalink to &quot;Re-run the failing tests&quot;">​</a></h2><p><strong>Piwi: Re-run the failing tests</strong> (<code>Ctrl+Shift+Alt+F</code>, <code>Cmd+Shift+Alt+F</code> on macOS, as <a href="/reference/editor-commands.html#keys">Keys</a> lists; <strong>Tools → Piwi → Re-run the failing tests</strong>) runs every test still failing, or edited since its run, one command per Playwright config, or those of one config from its node in the <a href="./editor-failures.html#the-failures-view">failures view</a>; when none fails, it says so.</p><h2 id="after-a-run" tabindex="-1">After a run <a class="header-anchor" href="#after-a-run" aria-label="Permalink to &quot;After a run&quot;">​</a></h2><p>Within a second of a run of the project ending, the editor reads the branch&#39;s latest run and its failures again, told by the instance&#39;s event stream; else every five minutes with the stream, every minute without. A checkout or a commit is noticed within seconds: the editor reads that run again and compares your application files with the new <code>HEAD</code>.</p><p>A run started from the editor is its own wherever it runs: the status bar follows it, the gutter shows each test as running, then its result, and its failures read <em>your run #124</em> once it ends. The editor learns the command&#39;s end and exit code from the process it started, in every shell, a rerun included. When no run on the instance carries its ref, it says why: its reporter sent nothing (its lines in the output name the server address, the key, or a refusal), or the config has no Piwi reporter: <code>The run ended (exit code 1) but did not reach https://piwi.example.com: is the Piwi reporter in the Playwright config?</code></p><h2 id="when-your-run-ends" tabindex="-1">When your run ends <a class="header-anchor" href="#when-your-run-ends" aria-label="Permalink to &quot;When your run ends&quot;">​</a></h2><p>Once a run you started from the editor, <a href="./terminal-runs.html">a terminal</a> (<code>run #125 in a terminal</code>) or the IDE&#39;s test runner is read, a notification says what it changed: <code>Piwi: run #124 · 1 of 3 CI failures fixed, 2 still failing (login.spec.ts › logs in, checkout.spec.ts › pays)</code> and new failures, with <strong>Open the failures</strong>, <strong>Open in dashboard</strong> and <strong>Re-run failing</strong>. The <code>piwi.runNotifications</code> setting (<strong>Settings → Tools → Piwi</strong> in JetBrains) shows it when a test fails, the default, always (a passing run then offers <strong>Only on failure</strong>), or never; <strong>Settings</strong> opens it in VS Code.</p><p>A CI run of your branch says the same once it ends, against the run it replaced: <code>Piwi: CI run #130 on feature-x · 2 fixed · 1 new failure (cart.spec.ts › adds)</code>. The <code>piwi.runNotificationsScope</code> setting, <strong>The runs it says it for</strong> in JetBrains, keeps it to the runs you started.</p><p>A <a href="/guide/concepts.html#verification">verification</a>, <strong>Verify ×3</strong>, runs the test three times without retries or breakpoints (<code>--repeat-each=3 --retries=0</code>), each run a result on the instance, and holds no failure. Its notification says how many passed, whatever the setting: <code>Piwi: run #124 · Passed 3 of 3</code>, or <code>Failed 1 of 3</code> with <strong>Open the failures</strong> and <strong>Open in dashboard</strong>, counted from the results the run streams (<code>Failed at least 1 of 3</code> when some were missed), else <a href="./editor-recording.html#run-it-or-verify-it-three-times">from its exit code</a>. Like a fix plan&#39;s verification and a Flake Lab line, it is listed, paused and stopped as any run.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-status-bar.html">The editor&#39;s status bar</a>: the latest run, the run in progress, and when the item turns red.</li><li><a href="./editor-failures.html">Failures in the editor</a>: the failures a run leaves, at their lines and in the failures view.</li><li><a href="./editor-connection.html">Editor connection</a>: the instance the editor reads, and its key.</li></ul>',22))])}const v=r(u,[["render",c]]);export{b as __pageData,v as default};
